style.css:
@-moz-document domain("134.122.29.243") {
/* Color principal rosado pastel */
  :root {
    --main-color: #ffc4d6;
  }

  /* Fondo blanco en todo el sitio */
  body, .pagelayout-mydashboard, .path-my {
    background-color: #ffffff !important;
  }

  /* Enlaces y botones con color rosado pastel */
  a, .btn, .btn-primary, .card-title a, .activityinstance a {
    color: var(--main-color) !important;
    border-color: var(--main-color) !important;
  }

  a:hover, .btn:hover, .btn-primary:hover {
    background-color: var(--main-color) !important;
    color: #fff !important;
  }

  /* Bordes y detalles */
  .card, .block, .activityinstance {
    border: 1px solid var(--main-color) !important;
    border-radius: 12px !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.05);
  }

  /* Cabeceras y títulos */
  h1, h2, h3, h4, .sectionname, .page-header-headings {
    color: var(--main-color) !important;
  }

  /* Botones activos o destacados */
  .btn-primary, .btn.btn-secondary, .btn.btn-outline-primary {
    background-color: var(--main-color) !important;
    border-color: var(--main-color) !important;
    color: white !important;
  }

  /* Bloques del dashboard */
  .block_myoverview, .block_timeline, .block_calendar_month {
    background-color: #fff !important;
    border: 1px solid #ffc4d6 !important;
  }

  /* Menú lateral y navbar */
  .navbar, .drawer, .drawer .list-group-item {
    background-color: #fff !important;
    border-right: 1px solid #ffc4d6 !important;
  }

  /* Quitar sombras fuertes y hacer todo más soft */
  * {
    box-shadow: none !important;
    outline: none !important;
  }
}
